mapper.select:
select cls.PTL_ID ptlId, cls.ASSET_POSITION assetPosition, sdl.ITEM_VALUE assetType, cls.FINPROD_ID finprodId, fp.FINPROD_NAME finprodName, cls.VAL_DATE valDate from CREDIT_LINES_SEC_POSITION cls left join FIN_PRODUCT fp on fp.FINPROD_ID = cls.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = fp.FINPROD_ID left join SYS_DATADICT_LIST sdl on sdl.ITEM_CODE = fpt.TYPE_8 and sdl.DICT_CODE = 'PINAN_ASSET_TYPE'
cls.PTL_ID = #{ptlId, jdbcType=VARCHAR}
and cls.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
and cls.PTL_ID = #{ptlId, jdbcType=VARCHAR}
and cls.VAL_DATE = to_date(#{valDate, jdbcType=DATE}, 'yyyy-mm-dd')
and fpt.TYPE_8 = #{assetType, jdbcType=VARCHAR}
and cls.ASSET_POSITION = #{assetPosition, jdbcType=VARCHAR}

select count(1) from FIN_PRODUCT t1, (select fpt.FINPROD_ID as finprodId from FIN_PRODUCT_TYPE fpt 
									left join SYS_DATADICT_LIST sdl on sdl.ITEM_VALUE = #{assetType}
									           and sdl.DICT_CODE = 'PINAN_ASSET_TYPE'
									 where fpt.TYPE_8 = sdl.ITEM_CODE) t2
		where t1.FINPROD_ID = t2.finprodId
		  and t1.FINPROD_MARKET_ID = #{assetCode}

mapper.insert:
insert into CREDIT_LINES_SEC_POSITION (SEQNO,VAL_DATE,PTL_ID,SUB_CODE,FINPROD_ID,CREDIT_OCCURE_TYPE, TRADE_AMT,ASSET_POSITION,CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME) select t1.SEQNO, t1.VAL_DATE, t1.PTL_ID, t1.SUB_CODE, t1.FINPROD_ID, t1.CREDIT_OCCURE_TYPE, t1.TRADE_AMT, t1.ASSET_POSITION, t1.CREATE_USER, t1.CREATE_DEPT, t1.CREATE_TIME, t1.UPDATE_USER, t1.UPDATE_TIME from (
select #{item.seqno, jdbcType=VARCHAR} SEQNO, #{item.valDate, jdbcType=DATE} VAL_DATE, #{item.ptlId, jdbcType=VARCHAR} PTL_ID, #{item.subCode, jdbcType=VARCHAR} SUB_CODE, #{item.finprodId, jdbcType=VARCHAR} FINPROD_ID, #{item.creditOccureType, jdbcType=VARCHAR} CREDIT_OCCURE_TYPE, #{item.tradeAmt, jdbcType=VARCHAR} TRADE_AMT, #{item.assetPosition, jdbcType=VARCHAR} ASSET_POSITION, #{item.createUser, jdbcType=VARCHAR} CREATE_USER, #{item.createDept, jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime, jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser, jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime, jdbcType=TIMESTAMP} UPDATE_TIME from DUAL
)t1
